import {FieldValidatorFn} from "../types/field-validator-fn";

// this code was entirely generated by claude
export const decimalValidator = (maxBefore: number, maxAfter: number): FieldValidatorFn => (value: string): string | null => {
    // regex checks if chars before comma and chars after comma are digits 0 to 9. It groups both numbers.
    const match = /^(\d+)(?:,(\d+))?-?$/.exec(value);
    if (!match) {
        return 'Keine gültige Dezimalzahl (nur Ziffern, Komma als Trenner, Minus ganz rechts).';
    }

    // we read the match. before is group 1, after is group 2 and might not be set. We use a default.
    const [, before, after = ''] = match;

    if (before.length > maxBefore) {
        return `Darf höchstens ${maxBefore} Vorkommastellen haben.`;
    }
    if (after.length > maxAfter) {
        return `Darf höchstens ${maxAfter} Nachkommastellen haben.`;
    }
    return null;
};